INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('You need to send an email requesting time off. What is the best subject line?', '["Hey", "URGENT!!!", "Leave Request - [Your Name] - [Dates]", "No subject line at all"]'::jsonb, 2, 'hr_behavioral', 'easy', true),
('During a meeting, your phone rings. What should you do?', '["Answer it and talk quietly", "Silence it and continue the meeting", "Step out loudly explaining who is calling", "Ignore the ringing and let it continue"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('You arrive late to a scheduled meeting. What is the best action upon entering?', '["Interrupt loudly to explain why you''re late", "Quietly enter, apologize briefly, and take a seat", "Skip the meeting entirely", "Blame traffic loudly in front of the group"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to address a professional email to someone you don''t know well?', '["\"Hey\"", "\"Yo\"", "\"Dear\" or \"Hi [Name],\"", "No greeting, just start writing"]'::jsonb, 2, 'hr_behavioral', 'easy', true),
('A colleague greets you in the morning. What is the most professional response?', '["Ignore them and keep working", "Greet them back briefly and warmly", "Complain about your day", "Walk away without responding"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Before joining a video call, what should you check first?', '["Nothing, just join immediately", "Your camera, microphone, and background", "Your phone notifications", "Your email inbox"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best practice when you know you will be late to a meeting?', '["Say nothing and just walk in late", "Notify the organizer in advance", "Skip it without notice", "Ask someone else to cover for you without telling anyone"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Your manager asks you to complete a task by Friday, but you''re unsure about a requirement. What is the best approach?', '["Guess and proceed silently", "Ask a clarifying question as soon as possible", "Wait until Friday to ask", "Work on a different task instead"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is proper etiquette when you need to leave a meeting early due to another commitment?', '["Just leave without saying anything", "Inform the organizer beforehand if possible", "Leave loudly complaining about the timing", "Never leave, and skip the other commitment"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Which is the best way to end a professional email?', '["No closing at all", "\"Bye\"", "\"Regards\" or \"Best regards,\" followed by your name", "A string of emojis"]'::jsonb, 2, 'hr_behavioral', 'easy', true),
('In a team brainstorming session, a colleague shares an idea you disagree with. What is the best response?', '["Say \"that''s a bad idea\" bluntly", "Stay silent and ignore them", "Acknowledge their idea and respectfully share your alternative view", "Interrupt them mid-sentence"]'::jsonb, 2, 'hr_behavioral', 'easy', true),
('What should you do if you receive a work email meant for someone else?', '["Ignore it", "Delete it", "Reply or forward it, informing the sender it was misdirected", "Read it and never mention it to anyone"]'::jsonb, 2, 'hr_behavioral', 'easy', true),
('What is the best time management habit for a busy workday?', '["Multitask on everything at once", "Prioritize tasks using a to-do list or planner", "Wait for your manager to assign priority to each task", "Work on whichever task is easiest first, regardless of urgency"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Your teammate is struggling with a task. What is the most collaborative response?', '["Ignore it, since it''s not your job", "Offer to help or share relevant resources", "Report them to the manager immediately", "Take over their task without asking"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the appropriate way to disagree with your manager''s decision?', '["Publicly criticize the decision in a team meeting", "Privately share your concerns with supporting reasons", "Comply silently while complaining to colleagues", "Ignore the instruction and do it your own way"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Which of these is the best practice for professional workplace communication?', '["Using slang and jargon others may not understand", "Being clear, concise, and respectful", "Sending long, unstructured messages", "Speaking only when directly asked"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('You made a small mistake in a report that has minimal impact. What should you do?', '["Hide it and hope no one notices", "Blame a colleague", "Acknowledge it, correct it, and inform relevant stakeholders", "Wait for someone else to find it"]'::jsonb, 2, 'hr_behavioral', 'easy', true),
('What is the best approach when scheduling a meeting with colleagues who have different workloads?', '["Schedule it at your own convenience only", "Send a poll or check availability before finalizing", "Assume everyone is free", "Schedule it without informing anyone"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('How should you respond when a colleague gives you constructive feedback?', '["Get defensive and argue", "Thank them and reflect on how to improve", "Ignore the feedback", "Criticize their work in return"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to start a professional email to a new client?', '["A brief, polite introduction and a clear purpose", "A long personal story", "An informal, chat-style greeting", "No introduction, straight into demands"]'::jsonb, 0, 'hr_behavioral', 'easy', true),
('Which behavior best demonstrates integrity at work?', '["Taking credit for a teammate''s work", "Reporting accurate results even if unfavorable", "Hiding mistakes from your manager", "Exaggerating achievements in reports"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What should you do before hitting "Reply All" on an email?', '["Nothing, always reply all to be safe", "Consider whether everyone truly needs to see your response", "Reply all by default", "Forward it to as many people as possible"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Your coworker takes credit for your idea in a meeting. What is the best immediate response?', '["Publicly accuse them of lying", "Calmly clarify your contribution with facts, professionally", "Say nothing and let it go permanently", "Complain to everyone except your coworker"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to prepare for a scheduled meeting?', '["Show up without any preparation", "Review the agenda and relevant materials beforehand", "Prepare only if asked to present", "Ask someone else to prepare for you"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('A deadline is approaching, and you realize you won''t finish on time. What is the best action?', '["Say nothing until the deadline passes", "Inform your manager early with a status update and revised plan", "Rush and submit incomplete work without mentioning it", "Blame the workload publicly"]'::jsonb, 1, 'hr_behavioral', 'easy', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('What is considered good etiquette in a group chat for work?', '["Sending numerous unrelated messages rapidly", "Keeping messages relevant, clear, and professional", "Using excessive emojis and abbreviations", "Ignoring the chat''s purpose entirely"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('When you don''t understand an instruction from your manager, what should you do?', '["Proceed with your best guess and say nothing", "Ask for clarification politely", "Ask a colleague instead of the manager", "Ignore the instruction"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to handle a colleague who consistently interrupts you in meetings?', '["Interrupt them back loudly", "Politely and assertively ask to finish your point", "Stop speaking in meetings altogether", "Complain about them behind their back"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What should be the tone of a professional workplace email?', '["Casual and full of slang", "Clear, respectful, and to the point", "Overly formal and robotic", "Sarcastic"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('You finish your assigned tasks early. What is the best next step?', '["Sit idle until told otherwise", "Ask your manager or team if they need help with anything", "Leave for the day without informing anyone", "Start unrelated personal work"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best response when a team member misses a deadline that affects your work?', '["Publicly criticize them in front of others", "Privately discuss the impact and find a solution together", "Complete their work without saying anything", "Report them immediately without discussion"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Which is the most professional way to decline a meeting invite you cannot attend?', '["Simply not show up", "Reply declining with a brief reason and suggest an alternative if possible", "Ignore the invite entirely", "Accept and then not attend"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to give feedback to a peer on their work?', '["Only point out flaws harshly", "Be specific, balanced, and constructive", "Avoid giving feedback to prevent conflict", "Criticize them in front of others"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Your manager praises you in front of the team for a group project. What is the best response?', '["Accept credit alone without mentioning the team", "Acknowledge and thank the team for their contribution too", "Downplay it awkwardly", "Ignore the praise entirely"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is a good practice before an important meeting when working remotely?', '["Test your internet connection and equipment in advance", "Join right at the exact start time without any check", "Assume everything will work fine", "Join late if there are issues"]'::jsonb, 0, 'hr_behavioral', 'easy', true),
('What should you do if you accidentally offend a colleague with a comment?', '["Ignore it and hope they forget", "Apologize sincerely and clarify your intent", "Avoid them from then on", "Justify the comment repeatedly"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('When writing a professional email, what should you always do before sending?', '["Send it immediately without checking", "Proofread for clarity, tone, and errors", "Add unnecessary details", "Copy everyone in the company"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to handle receiving negative feedback during a performance review?', '["Argue defensively with the reviewer", "Listen actively, ask clarifying questions, and create an improvement plan", "Dismiss the feedback as biased", "Immediately request a transfer"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Which best demonstrates good time management at work?', '["Working on tasks in random order", "Breaking tasks into priorities based on deadlines and importance", "Doing only tasks you enjoy first", "Waiting until the last minute for everything"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the appropriate way to ask a colleague for help on a task?', '["Demand they drop everything for you", "Politely explain what you need and check their availability", "Assign the task to them without asking", "Complain that no one helps you"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('In a job interview, when asked "What is your greatest weakness?", what is the best type of answer?', '["\"I have no weaknesses\"", "A genuine weakness with steps you''re taking to improve", "A weakness that''s actually a strength, exaggerated to sound humble", "A weakness unrelated to work entirely"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('When asked in an interview "Why do you want to work here?", what is the best approach?', '["\"I need a job\"", "Show genuine research about the company and alignment with your goals", "\"The salary is good\"", "Give a vague, generic answer"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to greet an interviewer at the start of an interview?', '["A firm handshake, eye contact, and a polite greeting", "A casual wave", "No greeting, just sit down directly", "An overly long personal introduction"]'::jsonb, 0, 'hr_behavioral', 'easy', true),
('If asked "Tell me about yourself" in an interview, what is the best approach?', '["Recite your entire life story", "Give a concise, relevant summary of your background and goals", "Talk only about your hobbies", "Ask why they want to know"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best attire guideline for a formal job interview unless told otherwise?', '["Casual streetwear", "Professional/business attire appropriate to the company culture", "Whatever is most comfortable regardless of setting", "Very flashy, attention-grabbing clothing"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What should you do if you don''t know the answer to a technical or behavioral interview question?', '["Make up an answer confidently", "Honestly acknowledge it and explain how you''d approach finding out", "Stay silent", "Change the subject abruptly"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to end a job interview?', '["Leave immediately without a word", "Thank the interviewer and ask about next steps", "Ask for the job on the spot aggressively", "Complain about the process"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('A recruiter asks if you have any questions at the end of the interview. What is the best response?', '["\"No, I have nothing to ask\"", "Ask a thoughtful question about the role or team", "Ask only about salary and vacation days", "Ask personal questions about the interviewer"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to follow up after a job interview?', '["Never follow up", "Send a brief, polite thank-you note within a day or two", "Call repeatedly every day", "Show up unannounced at the office"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Which behavior best reflects punctuality expectations in the workplace?', '["Arriving whenever convenient", "Arriving on time or a few minutes early for commitments", "Arriving significantly late regularly", "Skipping commitments without notice"]'::jsonb, 1, 'hr_behavioral', 'easy', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('What should you do if a scheduled meeting''s agenda is unclear to you beforehand?', '["Skip the meeting", "Ask the organizer for clarification on the agenda", "Assume and guess the topic", "Complain about the lack of agenda during the meeting"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is a good practice for taking notes during a meeting?', '["Rely purely on memory", "Jot down key points and action items", "Record everything without permission", "Avoid note-taking entirely"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('How should you handle it if you need to use your phone during a meeting for an urgent matter?', '["Use it silently without explanation", "Briefly excuse yourself and explain if needed", "Ignore the meeting and focus on the phone", "Argue that phones should always be allowed"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to show active listening during a conversation with a colleague?', '["Interrupt frequently with your own stories", "Maintain eye contact, nod, and respond thoughtfully", "Look at your phone while they speak", "Think about your reply instead of listening"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('If you strongly disagree with a group decision made by consensus, what is the best approach?', '["Sabotage the plan quietly", "Voice your concerns respectfully during discussion, then support the team decision", "Refuse to participate afterward", "Complain to outsiders about the team"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to respond to an email you received but need more time to properly answer?', '["Ignore it until you have a full answer", "Send a brief acknowledgment and an estimated response time", "Reply with an unrelated topic", "Wait indefinitely without any reply"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Which is the best way to build trust with new teammates?', '["Avoid interacting with them", "Be reliable, honest, and communicate consistently", "Promise things you can''t deliver to impress them", "Compete with them constantly"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What should you do if you are unsure whether an action is ethical at work?', '["Do it anyway if no one will notice", "Pause and consult company policy or a trusted supervisor", "Ask a friend outside the company", "Assume it''s fine since others do it"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the professional way to handle confidential company information?', '["Share it casually with friends", "Keep it strictly confidential per company policy", "Post about it on social media", "Discuss it loudly in public spaces"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('When collaborating on a shared document, what is the best practice?', '["Overwrite others'' work without notice", "Use comments or track changes and communicate edits", "Lock others out of editing", "Never edit shared documents"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the ideal way to respond when your idea is rejected in a team discussion?', '["Sulk and stop contributing", "Accept gracefully and continue contributing constructively", "Argue repeatedly until they change their mind", "Leave the discussion"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to introduce yourself at a professional networking event?', '["Talk only about yourself at length", "A brief, confident introduction with genuine interest in others", "Avoid speaking to anyone", "Hand out business cards without any conversation"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the recommended approach to managing your workload when given multiple tasks at once?', '["Try to do everything simultaneously and poorly", "Clarify priorities with your manager and organize accordingly", "Randomly pick tasks", "Refuse extra tasks outright"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('How should you respond if a colleague shares a personal problem affecting their work performance?', '["Ignore it and report only the performance issue", "Listen with empathy and, if appropriate, connect them to relevant support", "Gossip about it with others", "Dismiss it as none of your concern"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to handle a scheduling conflict between two important meetings?', '["Skip both meetings", "Communicate proactively with the organizers to prioritize or reschedule", "Attend neither and say nothing", "Randomly choose one without informing anyone"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Which is a hallmark of good email etiquette regarding response time?', '["Never responding", "Responding within a reasonable timeframe, even if just to acknowledge", "Responding only when convenient, regardless of urgency", "Responding with one-word answers only"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What should you do if you notice a typo in an email right after sending it?', '["Ignore it", "Send a brief follow-up correction if the error is significant", "Send ten follow-up emails apologizing", "Never send an email again"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to demonstrate reliability at work?', '["Occasionally meeting commitments", "Consistently following through on commitments and communicating proactively", "Promising more than you can deliver", "Avoiding commitments altogether"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best response to a coworker asking to borrow company equipment for personal use without approval?', '["Let them, since it''s harmless", "Politely explain you can''t authorize that and suggest they check with the appropriate person", "Report them immediately without discussion", "Do it yourself too"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Which is the most professional way to communicate a scheduling change to your team?', '["Assume everyone will figure it out", "Send a clear, timely notification to all affected parties", "Tell only your closest colleague", "Wait for someone to ask"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What should you prioritize first when starting a new job?', '["Making unrealistic promises to impress", "Learning processes, building relationships, and understanding expectations", "Criticizing existing processes immediately", "Avoiding interaction with the team"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('What is the best way to handle it when you are asked to work on a public holiday unexpectedly?', '["Refuse rudely", "Discuss your availability professionally and clarify expectations", "Agree without ever mentioning your prior plans, then resent it", "Ignore the request"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('When submitting a group assignment, what is the fairest practice regarding credit?', '["One person takes all the credit", "Accurately represent each member''s contribution", "Exclude a member''s name to reduce competition", "Randomly assign credit"]'::jsonb, 1, 'hr_behavioral', 'easy', true),
('Two teammates are in conflict over how to divide work, and it''s affecting the whole team''s progress. As a peer, what is the best approach?', '["Take sides publicly", "Facilitate a calm discussion where both share perspectives and find a compromise", "Ignore it since it''s not your issue", "Report both to management immediately without talking to them"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your manager publicly criticizes your work in a team meeting. What is the best way to handle this?', '["Argue back immediately in the meeting", "Stay professional in the meeting, then request a private conversation afterward", "Complain to colleagues about the manager", "Ignore it and shut down emotionally"]'::jsonb, 1, 'hr_behavioral', 'medium', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('You notice a colleague taking credit for a team''s collective work in front of senior management. What is the best approach?', '["Publicly contradict them in the meeting", "Address it privately with the colleague first, and escalate professionally if unresolved", "Say nothing to avoid conflict", "Spread the truth to other coworkers informally"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You''re leading a project and a team member consistently misses internal deadlines, though the client-facing deadline hasn''t been affected yet. What is the best action?', '["Wait until it becomes a client-facing issue", "Address the pattern early with the team member to understand causes and realign", "Report them to HR immediately", "Redo their work yourself without telling them"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('During a client meeting, a colleague provides incorrect information. What should you do?', '["Correct them harshly in front of the client", "Tactfully clarify or follow up afterward, correcting the record without embarrassing them", "Say nothing and let the client be misinformed", "Argue with your colleague loudly after the client leaves"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You are assigned a task outside your job description with no additional time allocated. What is the best response?', '["Refuse outright", "Discuss the added scope and its impact on your other priorities with your manager", "Silently do it while neglecting your actual responsibilities", "Do a poor job intentionally to discourage future requests"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A junior colleague asks for your help repeatedly, taking up significant time from your own work. What is the best approach?', '["Ignore their requests going forward", "Set boundaries by offering structured help, like scheduled check-ins, while explaining your workload", "Complain to your manager about them", "Snap at them to stop asking"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You realize partway through a project that the original plan approved by your manager won''t work. What is the best action?', '["Continue the flawed plan to avoid seeming difficult", "Proactively raise the issue with data and reasoning, and propose alternatives", "Quietly change the plan without informing anyone", "Wait until the deadline to reveal the issue"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team is divided on which approach to take for a project, causing delay. As a team member (not the lead), what is the best contribution?', '["Insist your own approach is correct and refuse to budge", "Present pros and cons objectively and support reaching a timely, data-informed decision", "Stay silent to avoid taking a side", "Escalate to management immediately without team discussion"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A coworker frequently makes off-color jokes that make you uncomfortable. What is the best first step?', '["Laugh along to fit in", "Privately and calmly tell them the jokes make you uncomfortable", "Complain to other coworkers about them", "Immediately file a formal HR complaint without addressing it directly first"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You are given negative feedback that you believe is partly unfair. What is the best response?', '["Accept everything without question", "Listen fully, then respectfully share your perspective with specific examples", "Reject the feedback outright", "Vent to coworkers about the unfairness"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team missed a major deliverable due to a shared oversight. In the post-mortem, what is the best approach?', '["Blame a specific teammate to protect yourself", "Focus on identifying root causes and process improvements rather than assigning blame", "Downplay the failure entirely", "Avoid discussing it to prevent awkwardness"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You''re asked to work with a colleague you previously had a disagreement with. What is the best approach?', '["Avoid them and minimize interaction", "Approach the collaboration professionally, focusing on shared goals", "Bring up the past disagreement to set the record straight first", "Ask to be reassigned immediately"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A tight project deadline requires overtime, but you have an important personal commitment. What is the best approach?', '["Cancel your commitment without informing anyone", "Communicate the conflict early and discuss possible solutions with your manager", "Skip work without notice", "Complete the work poorly to save time"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your manager assigns you a task that conflicts ethically with your personal values, such as slightly misrepresenting data. What is the best response?', '["Do it without question to keep your job", "Respectfully raise your concern and ask for clarification or an alternative approach", "Refuse loudly and report to the media", "Comply, but sabotage the results secretly"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You discover a significant error in a report already sent to a client. What is the best action?', '["Hope no one notices", "Promptly inform your manager and correct the client communication", "Quietly fix it in your files without notifying anyone", "Blame the software for the error publicly"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('As a new team member, you notice an inefficient process the team has used for years. What is the best approach?', '["Immediately criticize the process in your first week", "Observe, understand the reasoning, then suggest improvements diplomatically once you have context", "Say nothing indefinitely", "Silently change the process without approval"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Two of your direct reports are in a personal conflict affecting team morale. What is the best first step as their leader?', '["Ignore it, hoping it resolves itself", "Meet with each individually, then facilitate a joint conversation focused on resolution", "Publicly reprimand both in a team meeting", "Immediately reassign one of them without discussion"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You are overloaded with tasks and a new urgent request comes in from a different manager. What is the best approach?', '["Take it on silently and let existing work suffer", "Communicate your current workload transparently and negotiate priorities", "Refuse the new manager''s request outright", "Do the new task and ignore prior commitments without informing anyone"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A client is upset about a delay caused by your company. As the point of contact, what is the best response?', '["Blame internal teams to the client", "Acknowledge the issue, apologize appropriately, and provide a clear resolution plan", "Avoid the client''s calls", "Promise an unrealistic fix just to calm them down"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('During a brainstorming session, your idea gets criticized harshly by a senior colleague. What is the best response?', '["Shut down and stop contributing for the rest of the meeting", "Respond professionally, ask for specific feedback, and continue engaging constructively", "Criticize their idea back equally harshly", "Leave the meeting"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You''re asked in an interview: "Describe a time you disagreed with a team decision." What is the best type of answer?', '["Describe a conflict where you refused to cooperate", "Describe respectfully voicing disagreement, then supporting the team''s final decision constructively", "Say you never disagree with anyone", "Describe escalating over the team''s head to get your way"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('In an interview, you''re asked about a weakness related to time management. What is the best framing?', '["Deny ever having time management issues", "Briefly describe a real challenge and a concrete system or habit you built to address it", "Blame a previous employer for poor scheduling", "Give an unrelated technical weakness instead"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your manager takes an extended time to respond to your urgent question, delaying your work. What is the best action?', '["Wait indefinitely without progress", "Follow up politely, and in the meantime work on other tasks or flag a reasonable assumption", "Escalate immediately over your manager''s head", "Stop working entirely until they respond"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You receive an email from a colleague with an unnecessarily harsh, unprofessional tone. What is the best response?', '["Reply in an equally harsh tone", "Respond calmly and professionally, addressing the content, not the tone", "Ignore the email entirely", "Forward it to others to complain about the sender"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('During a group project, one member consistently contributes less than others. As a peer, what is the best first step?', '["Do their share of work quietly to avoid conflict", "Have a direct, respectful conversation to understand the reason and realign expectations", "Report them to the professor or manager immediately without discussion", "Publicly call them out in front of the group"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You''re asked to give a presentation with very short notice. What is the best approach?', '["Refuse due to insufficient time", "Accept, focus on key points, and clearly communicate any limitations given the short timeframe", "Present unprepared without acknowledging it", "Delegate the entire presentation to someone else without asking"]'::jsonb, 1, 'hr_behavioral', 'medium', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('In a meeting, you realize the group is going off-topic and wasting time. As a participant (not the leader), what is the best approach?', '["Stay silent, even though time is being wasted", "Politely redirect the conversation back to the agenda", "Interrupt rudely and take control of the meeting", "Leave the meeting"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team''s project is behind schedule due to unclear initial requirements from a stakeholder. What is the best next step?', '["Continue guessing at requirements to save time", "Schedule a clarification meeting with the stakeholder promptly", "Blame the stakeholder publicly", "Pause the project indefinitely without communication"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A colleague asks you to cover for their mistake to their manager. What is the best response?', '["Agree to protect the relationship", "Decline to lie, but offer to support them in addressing it honestly", "Report them immediately without talking to them first", "Ignore the request and say nothing to anyone"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You''ve been given unclear instructions by a senior leader who seems too busy to clarify. What is the best approach?', '["Guess entirely and proceed without any confirmation", "Summarize your understanding in a brief message and ask for a quick confirmation", "Wait indefinitely until they have time", "Ask a junior colleague to decide for you"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('In a performance review, your manager says you need to improve collaboration skills but gives no specifics. What is the best response?', '["Accept it without seeking more information", "Politely ask for specific examples and actionable suggestions", "Argue that the feedback is invalid", "Assume it''s a mistake and ignore it"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team wants to try a new approach you believe is risky, but you''re not the decision-maker. What is the best approach?', '["Comply silently despite serious concerns", "Voice your concerns with reasoning, then support the decision if it proceeds", "Sabotage the approach quietly to prove it wrong", "Refuse to participate in the project"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('During onboarding, you feel overwhelmed by the volume of new information. What is the best approach?', '["Pretend to understand everything", "Take notes, ask clarifying questions, and request follow-ups as needed", "Avoid asking questions to appear competent", "Give up on retaining information"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A cross-functional teammate from another department isn''t responding to your requests, delaying your work. What is the best next step?', '["Escalate to their manager immediately without contacting them again", "Send a polite follow-up, and if unresponsive after reasonable attempts, loop in relevant leads", "Give up on the task entirely", "Publicly call them out in a group channel"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You''re asked "How do you handle stress and pressure?" in an interview. What is the best type of answer?', '["\"I never get stressed\"", "Describe specific coping strategies and give a real example of managing pressure effectively", "Describe becoming overwhelmed and shutting down", "Say stress isn''t something you think about"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team lead assigns you a task with an unrealistic deadline. What is the best first step?', '["Miss the deadline silently", "Refuse the task outright", "Communicate the constraint and propose a realistic plan", "Complain to other teammates"]'::jsonb, 2, 'hr_behavioral', 'medium', true),
('You discover that a close friend at work violated a minor company policy. What is the best action?', '["Ignore it since they''re a friend", "Address it honestly, encouraging them to correct it or report it appropriately, based on severity", "Cover for them completely", "Immediately report to senior management without speaking to your friend"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your manager assigns credit for a project to another team unfairly. What is the best approach?', '["Publicly dispute it in a company-wide meeting", "Raise the concern privately with your manager, providing evidence of your contribution", "Say nothing and resign", "Complain to other colleagues about unfairness"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('In an interview, you''re asked about a past failure. What is the best structure for your answer?', '["Deny ever failing at anything", "Briefly describe the failure, what you learned, and how you applied that learning afterward", "Blame external factors entirely", "Describe a minor, irrelevant failure to avoid real vulnerability"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team is asked to cut corners on quality to meet a deadline. What is the best response as a team member?', '["Comply without question", "Raise concerns about the tradeoff and suggest options like adjusting scope or timeline", "Refuse to work on the project entirely", "Quietly reduce quality without telling anyone"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A colleague constantly checks messages and emails during meetings, seeming disengaged. As a peer, what is the best approach?', '["Call them out publicly in the meeting", "Speak with them privately afterward about the impact of their behavior", "Ignore it entirely", "Report them to HR immediately"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You receive conflicting instructions from two different supervisors. What is the best approach?', '["Follow whichever supervisor you prefer without telling the other", "Bring both together, or communicate between them, to clarify priorities", "Do nothing until they resolve it themselves", "Do both tasks poorly to save time"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A teammate shares an idea in a meeting that is very similar to one you suggested privately earlier, without crediting you. What is the best approach?', '["Publicly accuse them of stealing your idea", "Build on the idea supportively in the meeting, and privately clarify the origin afterward if needed", "Refuse to contribute further to the discussion", "Complain to other teammates afterward"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your manager assigns you a high-visibility project you feel unprepared for. What is the best response?', '["Decline out of fear", "Accept, express your enthusiasm, and ask about resources or support available", "Accept but secretly do minimal effort", "Accept and pretend to have all needed skills without seeking support"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('During a heated team debate, tempers start rising. As a participant, what is the best action?', '["Escalate further to \"win\" the argument", "Suggest a short pause or refocus the conversation on facts and shared goals", "Leave without resolution", "Stay silent and let the conflict continue"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You are asked to mentor a new hire who seems resistant to your guidance. What is the best approach?', '["Give up mentoring them immediately", "Understand their perspective, adjust your approach, and remain patient and clear", "Report their attitude to management right away", "Force your methods without discussion"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your project''s success depends on a vendor who is delayed. What is the best action to take?', '["Wait passively for the vendor", "Proactively follow up with the vendor and develop a contingency plan", "Blame the vendor publicly to stakeholders", "Cancel the project without exploring alternatives"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You are asked "How do you prioritize tasks when everything seems urgent?" in an interview. What is the best answer approach?', '["\"I just do everything at once\"", "Describe a clear method, such as assessing impact and urgency, with a real example", "\"I ask my manager to decide everything\"", "\"I do whatever is easiest first\""]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A colleague frequently arrives late to team meetings, delaying the start each time. As the meeting organizer, what is the best approach?', '["Publicly embarrass them each time they''re late", "Privately discuss the pattern and its impact, and agree on a solution", "Start excluding them from meetings without discussion", "Say nothing and let it continue"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You''re given feedback anonymously through a survey that feels overly critical without context. What is the best response?', '["Dismiss it since it''s anonymous", "Reflect on any valid points and consider seeking further clarifying feedback through appropriate channels", "Try to find out who wrote it to confront them", "Become defensive with your whole team"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team must choose between two vendors, and you have a personal relationship with one of them. What is the best approach?', '["Push strongly for your personal contact without disclosure", "Disclose the relationship and let objective criteria and other stakeholders guide the decision", "Stay silent about the relationship", "Excuse yourself from all vendor discussions permanently"]'::jsonb, 1, 'hr_behavioral', 'medium', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('A remote teammate seems to be less responsive lately, possibly affecting their output. What is the best first step?', '["Assume they''re slacking off and report them", "Check in with genuine concern to understand what might be happening", "Publicly question their commitment in a team channel", "Ignore it and reassign their work quietly"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('In an interview, you''re asked to describe your leadership style. What is the best type of answer?', '["\"I don''t have a leadership style\"", "Describe an authentic style with a concrete example showing its effectiveness", "Claim to be the perfect leader with no growth areas", "Describe controlling every decision as the ideal style"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You are asked to complete a task using a method you believe is outdated or inefficient. What is the best approach?', '["Refuse to use the method", "Use the required method for now while respectfully suggesting an alternative for future consideration", "Use your own method secretly without informing anyone", "Complain about the method to colleagues instead of raising it appropriately"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team''s shared calendar shows a double-booking for an important meeting room. What is the best action?', '["Take the room regardless of the other booking", "Communicate with the other team to resolve the conflict, or find an alternative room", "Cancel your meeting without explanation", "Wait and see who shows up first"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A stakeholder requests a change that will significantly delay the project timeline. What is the best response?', '["Agree immediately without discussing the timeline impact", "Clearly communicate the tradeoffs of time, cost, and scope before agreeing", "Refuse the change outright", "Silently absorb the delay without informing anyone"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You overhear a colleague being unfairly criticized by another employee behind their back. What is the best action?', '["Join in the criticism", "Avoid participating and, if appropriate, address it directly or encourage constructive resolution", "Report it anonymously without ever addressing it directly", "Tell the criticized colleague exactly what was said in a dramatic way"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your workload increases significantly after a teammate leaves the company, with no replacement hired yet. What is the best approach?', '["Silently absorb all the extra work indefinitely", "Communicate the situation to your manager and discuss reprioritization or support", "Reduce quality across all tasks without informing anyone", "Refuse any additional responsibilities"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('During a group interview or discussion, another candidate is dominating the conversation. What is the best approach for you?', '["Compete by talking over them", "Wait for a natural pause and contribute your points confidently and respectfully", "Stay silent for the entire session", "Directly criticize the other candidate''s behavior"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You are asked to travel for work on short notice, conflicting with a family event. What is the best approach?', '["Refuse abruptly without explanation", "Communicate the conflict honestly and explore possible alternatives with your manager", "Go without telling anyone about the conflict, then resent it", "Agree, then cancel last minute without notice"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your proposal was rejected in favor of a colleague''s similar but less-developed idea. What is the best response?', '["Argue that the decision was clearly wrong", "Accept the decision professionally and offer your insights to help strengthen the chosen approach", "Refuse to support the chosen idea", "Complain to others about the unfairness"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('In an interview you''re asked, "How do you handle working with someone whose style differs from yours?" What is the best answer approach?', '["\"I avoid working with people unlike me\"", "Describe adapting your approach and finding common ground while respecting differences", "\"I insist they work my way\"", "\"It never happens to me\""]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your manager asks for your honest opinion on a plan you think has flaws. What is the best response?', '["Say it''s perfect to avoid conflict", "Share your honest, constructive assessment with supporting reasons", "Stay vague to avoid taking a position", "Criticize it harshly without offering alternatives"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You''ve been assigned to a team project with a history of poor communication. What is the best proactive step?', '["Assume it will resolve itself", "Suggest establishing clear communication norms early, such as regular check-ins", "Work independently and avoid the team entirely", "Complain to management before the project starts"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your coworker asks you to help them prepare for their own promotion interview against you for the same role. What is the best approach?', '["Refuse to help out of self-interest", "Offer genuine, appropriate support while continuing to prepare well yourself", "Give them misleading advice", "Report them for asking"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('A client sends an angry email with unprofessional language. What is the best response approach?', '["Reply in kind, matching their tone", "Respond calmly and professionally, addressing their concerns directly", "Ignore the email until they calm down", "Forward it to colleagues to vent about the client"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('During a project retrospective, you feel personally responsible for a failure, but no one has mentioned it yet. What is the best approach?', '["Stay quiet and hope it''s not discussed", "Proactively and calmly own your part, focusing on lessons learned", "Downplay your role if asked directly", "Blame the process instead of acknowledging your role"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You are asked in an interview: "Tell me about a conflict with a coworker and how you resolved it." What is the best structure for your answer?', '["Describe the conflict in a way that blames the coworker entirely", "Describe the situation objectively, your actions to resolve it, and the positive outcome", "Say you''ve never had a conflict", "Focus mainly on how upset you were"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your team members disagree on how to split final presentation duties, and the deadline is near. What is the best approach?', '["Let it remain unresolved and present disorganized", "Suggest a quick, fair method, such as dividing roles based on strengths, and move forward", "Take over all duties yourself", "Insist on doing it exactly your way"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You notice a new employee looks lost and hasn''t asked for help despite clearly needing it. What is the best action?', '["Assume they''ll figure it out eventually", "Proactively offer help and answer questions in a welcoming way", "Wait for them to fail before stepping in", "Report their struggle to their manager immediately"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('Your manager assigns a task, then a second manager assigns a conflicting task with the same deadline, unaware of each other. What is the best action?', '["Try to secretly do both quickly and superficially", "Inform both managers of the conflict and ask them to help prioritize", "Pick one silently and hope the other doesn''t notice", "Refuse both tasks"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('In an interview, you''re asked why you''re leaving or left your previous job. What is the best type of answer?', '["Harshly criticize your former employer", "Give a professional, forward-looking reason focused on growth or opportunity", "Say you were forced to leave without context", "Avoid answering the question directly"]'::jsonb, 1, 'hr_behavioral', 'medium', true),
('You discover your close friend and teammate is quietly job hunting, which isn''t against any actual policy. Your manager asks if you know anything about morale issues on the team. What is the best response?', '["Reveal your friend''s job search to be fully transparent", "Keep your friend''s personal decision confidential while honestly addressing any legitimate morale concerns you can speak to", "Lie and say everything is perfect", "Refuse to answer the manager at all"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You''re leading a project where a highly skilled but difficult teammate consistently produces excellent individual work but undermines team cohesion. What is the best approach?', '["Remove them immediately to protect morale", "Have a direct conversation addressing specific behaviors and their impact, setting clear expectations before considering other action", "Ignore the behavior since their output is valuable", "Publicly reprimand them to make an example"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You''re asked by your manager to give a peer a positive performance review, even though you know their performance has genuine issues that could affect a client project. What is the best response?', '["Give the positive review as asked to avoid conflict with your manager", "Respectfully explain your honest observations to your manager and provide an accurate assessment", "Give a harshly negative review to counter the pressure", "Refuse to submit a review at all"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Two equally qualified, hardworking teammates are up for the same single promotion, and you''re asked for input as their peer. What is the best approach?', '["Recommend whichever one is your closer friend", "Give an objective, evidence-based assessment of each person''s strengths relevant to the role", "Refuse to give any input to avoid picking a side", "Recommend neither, even if asked directly for a comparison"]'::jsonb, 1, 'hr_behavioral', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Your team is close to a deadline when you discover a fundamental flaw that would require significant rework, likely causing you to miss the deadline either way. What is the best approach?', '["Ship the flawed version to hit the deadline and fix it later quietly", "Immediately inform stakeholders with a clear explanation, impact assessment, and options", "Hide the flaw and hope no one notices", "Blame a teammate for the flaw to deflect responsibility"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You are up for a promotion, and a rival colleague privately asks for help on the exact skill area you''re both being evaluated on. What is the best approach?', '["Refuse to help since it might hurt your own chances", "Offer genuine, reasonable help while maintaining your own preparation and performance", "Give intentionally poor advice", "Report the colleague for asking, framing it as an unfair advantage"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Your manager consistently takes credit for your ideas in front of senior leadership, but is otherwise supportive of your career. What is the best approach?', '["Confront them angrily in front of leadership to set the record straight", "Have a private, calm conversation with your manager about how you''d like to be credited going forward", "Say nothing and continue as normal indefinitely", "Go over your manager''s head immediately to complain"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You are asked in a final-round interview to describe your greatest professional failure. You genuinely have one that was serious and partly your fault. What is the best approach?', '["Choose a trivial, low-stakes example instead to appear safer", "Honestly describe the real failure with accountability and clear lessons learned and applied", "Describe a failure and blame external circumstances mostly", "Say you can''t recall any significant failures"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('A teammate you informally guide confides they are struggling with burnout and asks you not to tell anyone, but their declining output is starting to affect the whole team''s deadline. What is the best approach?', '["Immediately report it to management, breaking their confidence entirely", "Encourage them to seek support or talk to their manager themselves, and discuss how the team can adjust in the meantime", "Say nothing and let the team miss the deadline", "Take on all of their remaining work yourself silently"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You''re asked to choose between two project approaches: one meets the letter of a client''s request but underserves their actual underlying need; the other addresses the real need but deviates from what was explicitly requested. What is the best approach?', '["Silently deliver what best serves the underlying need without mentioning the deviation", "Raise the discrepancy with the client, explain your reasoning, and let them decide with full information", "Strictly follow the literal request without any discussion", "Deliver a compromise without informing the client of either consideration"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('During a heated conflict, your teammate says something you consider a personal insult in the middle of a stressful deadline. What is the best in-the-moment response?', '["Insult them back to defend yourself", "Stay composed, address the specific issue, and revisit the interpersonal matter privately later", "Walk out of the workspace without a word", "Escalate to management immediately mid-crisis"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Your manager asks you to falsify a minor detail in a report to make a project look slightly more on-track than it is, framing it as "not a big deal." What is the best approach?', '["Comply since it''s a small detail and your manager asked", "Respectfully decline, explain your concern, and suggest an honest way to frame the actual status", "Report your manager to their superior immediately without discussion", "Falsify it but keep a secret record in case it''s discovered later"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You are the only one who notices a colleague from another team is about to make a costly decision based on outdated information, but it''s not your area, and speaking up might overstep. What is the best approach?', '["Say nothing since it''s not your area", "Politely and respectfully share the updated information relevant to their decision", "Loudly announce their mistake in a group setting to ensure it''s noticed", "Wait to see if the mistake happens, then criticize afterward"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('In your first month at a new job, you realize a well-liked senior colleague''s long-standing process contains a moderate but real error affecting output quality. What is the best approach?', '["Say nothing since you''re new and they''re well-liked", "Respectfully raise the observation, perhaps by asking questions rather than asserting, to open dialogue", "Immediately report the error to upper management", "Fix it yourself silently without telling anyone"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('A hiring manager asks you a question that feels inappropriate, touching on your personal life in a way unrelated to the job. What is the best response?', '["Answer fully and openly regardless of discomfort", "Politely redirect to how your qualifications relate to the role, without being confrontational", "Refuse to answer and end the interview abruptly", "Answer with visible irritation"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You are asked to lead a project team that includes someone senior to you in tenure, though not in title, who seems resistant to taking direction from you. What is the best approach?', '["Assert authority forcefully to establish control", "Build credibility through clear communication, respect for their experience, and collaborative decision-making", "Avoid giving them any tasks to prevent friction", "Escalate to management immediately to force compliance"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Late in a project, a stakeholder requests a change that is technically feasible but ethically questionable regarding user privacy, and refusing might harm the client relationship. What is the best approach?', '["Comply fully to protect the relationship", "Raise the ethical concern clearly with the stakeholder and propose alternatives that address their goal appropriately", "Quietly implement it while documenting your objection privately, without telling the stakeholder", "Refuse and immediately end the engagement without discussion"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You are asked in an interview about a time you had to make a decision without complete information. What is the best type of answer to give?', '["Say you always wait for complete information before deciding", "Describe a real situation, your reasoning process under uncertainty, and the outcome and lessons", "Say you always defer such decisions to someone else", "Describe guessing randomly and it working out"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Your team consistently succeeds due to one dominant, high-performing member, but their approach discourages others from contributing ideas. As their peer, what is the best approach?', '["Say nothing since results are good", "Privately encourage them to invite more input, framing it as strengthening the team''s overall output", "Publicly undermine their ideas to make room for others", "Complain to management to have them removed"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You''re torn between two pieces of feedback: your manager wants speed, and your teammate, a subject matter expert, insists more time is needed for quality. What is the best approach as the one responsible for delivery?', '["Follow whichever person has more authority without question", "Facilitate a conversation between both, or synthesize their input, to find a workable tradeoff, then communicate the plan clearly", "Ignore both and decide entirely on your own without input", "Delay indefinitely until they agree"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('A colleague privately admits to you that they exaggerated their qualifications during hiring, and they''re now visibly struggling to keep up. What is the best approach?', '["Report them immediately to HR without talking to them", "Encourage them to seek support or training and be honest with their manager, while avoiding actively covering for ongoing performance gaps", "Help them hide the struggle indefinitely", "Tell other coworkers so they know not to rely on this person"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('In an interview, you''re asked to describe a time you had to give unwelcome feedback to someone. What is the best structure for the answer?', '["Describe avoiding giving feedback because it''s uncomfortable", "Describe delivering specific, constructive, respectful feedback, and the resulting outcome", "Describe giving harsh feedback to assert authority", "Describe giving vague feedback to soften the blow"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Your team''s success metric rewards speed, but you notice cutting a corner would technically satisfy the metric while quietly reducing real value to end users. What is the best approach?', '["Cut the corner since it meets the metric", "Raise the disconnect between the metric and true value with your manager, and propose maintaining actual quality", "Cut corners without telling anyone since it''s not against the rules", "Refuse to work on the project at all"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You are given a stretch assignment with high visibility, but midway through you realize you''re in over your head. What is the best approach?', '["Continue silently struggling to avoid appearing incapable", "Proactively communicate the challenge and ask for specific support or guidance", "Quietly hand the task to a teammate without telling your manager", "Abandon the task without explanation"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Your manager gives you consistently vague positive feedback such as "good job" that doesn''t help you grow, while you sense there may be unaddressed areas for improvement. What is the best approach?', '["Assume everything is perfect and stop seeking further input", "Proactively ask for specific, actionable feedback on particular areas", "Assume the vague feedback means something is being hidden and become anxious", "Complain that your manager isn''t a good manager"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('During a job interview, you''re asked to comment on a previous employer who treated you unfairly. What is the best approach for framing your answer?', '["Describe the unfair treatment in full emotional detail", "Briefly and professionally describe the situation factually, focusing on what you learned and how you handled it constructively", "Refuse to answer the question at all", "Say the previous employer was entirely to blame with no self-reflection"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You lead a diverse team where two members have a cultural miscommunication causing tension, though neither intended offense. What is the best approach as the leader?', '["Ignore it since no one intended harm", "Facilitate an open conversation to build mutual understanding and establish clearer norms going forward", "Reprimand both equally without discussion", "Reassign one of them immediately to avoid the issue"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You are asked to choose a team member to let go during downsizing, and the two weakest performers are a longtime loyal employee and a newer, more technically skilled one. What is the best approach to the decision process?', '["Base the decision purely on tenure and loyalty", "Base the decision on objective criteria such as current performance, skills needed, and future contribution, applied consistently and fairly", "Let the affected employees decide between themselves", "Avoid making a decision and let attrition resolve it naturally"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('In an interview, you''re asked how you''d handle disagreeing with a company policy after being hired. What is the best type of answer?', '["Say you''d always follow policy without question, no matter what", "Say you''d raise concerns through appropriate channels while respecting the decision-making process", "Say you''d ignore policies you disagree with", "Say you''d publicly criticize the policy to coworkers"]'::jsonb, 1, 'hr_behavioral', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Your close mentor at work asks you to support their controversial proposal in an upcoming meeting, even though you have genuine reservations about it. What is the best approach?', '["Support it fully to preserve the relationship, regardless of your reservations", "Share your honest, respectful assessment, including both merits and concerns, even if it differs from your mentor''s view", "Oppose it strongly to prove your independence", "Stay silent in the meeting to avoid the dilemma"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You discover that meeting an aggressive deadline would require your team to work unsustainable hours for weeks, risking burnout, but missing it has real business consequences. As team lead, what is the best approach?', '["Push the team to meet the deadline regardless of the human cost", "Transparently present the tradeoffs to stakeholders and negotiate scope, timeline, or resources to find a sustainable path", "Quietly let the team decide informally without stakeholder involvement", "Miss the deadline without any communication or explanation"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('During a merger, employees from another team with a different work culture join yours, causing friction over differing norms such as communication styles. What is the best approach as a team member?', '["Insist the newcomers adapt entirely to existing norms", "Engage in open dialogue to understand differences and collaboratively establish shared norms", "Avoid interacting with the new team members", "Complain to management to have norms unilaterally enforced"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You''re asked in an interview: "Tell me about a time you had to influence someone without direct authority over them." What is the best structure for the answer?', '["Describe using authority you didn''t actually have", "Describe building a case through data, relationships, and persuasion to gain buy-in, with a concrete outcome", "Describe giving up because you lacked authority", "Describe going around the person to their manager immediately"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Your team must decide between a safer, mediocre solution and a riskier, potentially much better one, under time pressure and with incomplete data. As a contributor, what is the best approach?', '["Push hard for your personal preference alone without input from others", "Facilitate a structured discussion weighing risk, potential upside, and reversibility, then support the team''s informed decision", "Avoid the decision and let others handle it entirely", "Insist on delaying the project until full data is available, regardless of the deadline"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('You suspect, but aren''t certain, that a colleague is misrepresenting their hours worked. What is the best first step?', '["Publicly accuse them based on suspicion", "Gather clear observations, then raise the concern through the appropriate confidential channel rather than confronting or accusing directly", "Ignore it since you''re not certain", "Tell other coworkers your suspicion to see if they agree"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('In an interview, you''re asked to describe handling a situation where you had to deliver bad news to a stakeholder or client. What is the best structure for your answer?', '["Describe softening the news so much the stakeholder didn''t understand the real impact", "Describe delivering the news clearly and honestly, with context and a plan forward", "Describe delaying the bad news as long as possible", "Describe having someone else deliver it for you"]'::jsonb, 1, 'hr_behavioral', 'hard', true),
('Your organization asks employees to volunteer unpaid overtime "for team spirit" during a crunch period, and you feel uncomfortable but don''t want to seem uncommitted. What is the best approach?', '["Comply silently despite discomfort to avoid seeming uncommitted", "Have an honest conversation with your manager about your capacity and any concerns, proposing sustainable alternatives", "Refuse publicly and criticize the request to the whole team", "Comply outwardly while doing minimal actual work in protest"]'::jsonb, 1, 'hr_behavioral', 'hard', true);
